    """Mirror each row horizontally, then stack rows as reversed, original, reversed."""
    rows = [list(row) for row in grid]
    out = []
    for block in (rows[::-1], rows, rows[::-1]):
        for row in block:
            out.append(row[::-1] + row)
    return out
